using UnityEngine;
public partial class DungeonPrototype {
 CombatHack systemHack;PlayerHackDefinition systemHackDefinition;bool systemHackPending;
 CodeboundSystemMessages SystemMessages {get{return CodeboundSystemMessages.For(gameObject);}}
 void BeginHackSystemSession(CombatHack hack){systemHack=hack;systemHackDefinition=HackCatalog!=null?HackCatalog.Find(selectedHackId):null;systemHackPending=true;string name=systemHackDefinition!=null?systemHackDefinition.displayName:hack.DisplayName;name=(name??"").ToUpperInvariant();if(name.EndsWith(".EXE",System.StringComparison.Ordinal))name=name.Substring(0,name.Length-4);SystemMessages.Show(SystemMessageCode.HackInitialized,name,0,DigitalIcon.SystemRepair,systemHackDefinition!=null&&systemHackDefinition.systemMessages!=null?systemHackDefinition.systemMessages.initialized:null);}
 void CompleteHackSystemSession(HackExecutionOutcome outcome){if(!systemHackPending)return;systemHackPending=false;SystemMessageCode code=outcome==HackExecutionOutcome.Success?SystemMessageCode.HackSuccess:outcome==HackExecutionOutcome.Perfect?SystemMessageCode.HackPerfect:outcome==HackExecutionOutcome.Failed?SystemMessageCode.HackFailed:outcome==HackExecutionOutcome.Interrupted?SystemMessageCode.HackInterrupted:SystemMessageCode.HackComplete;var profile=systemHackDefinition!=null?systemHackDefinition.systemMessages:null;SystemMessages.Show(code,systemHackDefinition!=null?systemHackDefinition.displayName:"",0,outcome==HackExecutionOutcome.Failed||outcome==HackExecutionOutcome.Interrupted?DigitalIcon.Denied:DigitalIcon.Granted,profile!=null?profile.Result(outcome):null);systemHack=null;systemHackDefinition=null;}
 void UpdateHackSystemSession(){if(systemHackPending&&(systemHack==null||!systemHack.isActiveAndEnabled||!systemHack.Active)){CompleteHackSystemSession(HackExecutionOutcome.Interrupted);if(battle){busy=false;selectingEnemy=false;pendingTargetHack=null;}}}
 void NotifyHealing(CombatItemDefinition item,int healed){SystemMessageCode code=item.digitalIcon==DigitalIcon.SystemRepair?SystemMessageCode.HealRepair:item.digitalIcon==DigitalIcon.FullRestore?SystemMessageCode.HealFull:SystemMessageCode.HealPatch;SystemMessages.Show(code,item.displayName,healed,item.digitalIcon);}
}
